  ["_CeladonMart4FSuperNerdText"] = "Busco un regalo\npara COPYCAT, de\11CIUDAD CELESTE.\12Tiene que ser una\nPOKé MUÑECA.\11¡Están de moda!",
  ["_CeladonMart4FYoungsterText"] = "¡Me dijeron una\ncosa!\12¡Puedes huir de\nun POKéMON\11salvaje si le\11distraes con una\11POKé MUÑECA!",
  ["_CeladonMart5FCurrentFloorSignText"] = "P4: FARMACIA",
  ["_CeladonMart5FGentlemanText"] = "¡Los dispositivos\nde mejora de los\11POKéMON sólo\11se venden aquí!\12Usa CALCIO para\naumentar las\11habilidades\11ESPECIALES.\12Usa CARBO-\nHIDRATOS para\11aumentar la\11VELOCIDAD.",
  ["_CeladonMart5FSailorText"] = "¡He venido a por\ndispositivos de\11mejora de los\11POKéMON!\12Las PROTEÍNAS\naumentan la\11potencia del\11ATAQUE.\12El HIERRO aumenta\nla DEFENSA.",
  ["_CeladonMartRoofCurrentFloorSignText"] = "ÚLTIMO PISO:\nDISTRIBUIDORES",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "¡Tengo sed!\n¡Me gustaría\11beber algo!\12¿Le das algo\nde beber?",
