  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "¡Yay!\12¡AGUA!\12¡Gracias!\12¡Tómala,\ntoda tuya!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "¡Genial!\12¡LIMONADA!\12¡Gracias!\12¡Tómala,\ntoda tuya!",
