  ["_CeladonPokecenterGentlemanText"] = "¡La POKé FLAUTA\ndespierta a los\11POKéMON con un\11sonido que sólo\11ellos pueden oír!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "El ATAQUE de todo\nPOKéMON\11aumenta un poco.\12Y podrás usar el\nDESTELLO siempre\11que quieras.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "Los POKéMON de\nnivel inferior a\v30 te obedecerán.\12¡Los de nivel\nsuperior, serán\11incontrolables!\12Y podrás usar\nCORTAR fuera del\11combate.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "¡Todos los\nPOKéMON\11te obedecerán!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "Los POKéMON de\nnivel inferior a\v70 te obedecerán.\12¡Los de nivel\nsuperior serán\11incontrolables!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Sólo tienen\nMEDALLAS los\11entrenadores\11más hábiles.\12Ya veo que tienes\nuna por lo menos.\12¡Esas MEDALLAS\nguardan secretos\11increíbles!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Ven a verme\ncuando quieras.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dime...\12¿Cuál de las 8\nMEDALLAS debería\11describirte?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "Los POKéMON de\nnivel inferior a\v50 te obedecerán.\12¡Los de nivel\nsuperior serán\11incontrolables!\12Y podrás usar la\nFUERZA fuera del\11combate.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DEFENSA de\ntodos los POKéMON\11aumenta un poco.\12Y podrás usar el\nSURF fuera del\11combate.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCIDAD de\ntodos los POKéMON\11aumenta un poco.\12Y podrás utilizar\nVOLAR fuera del\11combate.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Las habilidades\nESPECIALES de\11tus POKéMON\11aumentan un poco.",
  ["_CeruleanCityBikeShopSign"] = "¡Hierbas y cuevas\nbajo control!\11TIENDA-BICIS",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "¡SLOWBRO dale un\npuñetazo! ¡No!\11¡Volviste a\11fallar!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "¡BIEN! ¡SLOWBRO!\n¡Usa la BOMBA\11SÓNICA! ¡Venga,\11SLOWBRO, presta\11atención!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "¡SLOWBRO, APARTA!\n¡No! ¡Qué mal!\12¡Es tan difícil\ncontrolar a los\11POKéMON!\12¡La obediencia de\ntus POKéMON\11depende de tus\11habilidades como\11entrenador!",
  ["_CeruleanCityCooltrainerF2Text"] = "Quiero una bonita\nBICICLETA roja.\12¡La guardaré en\ncasa para que no\11se ensucie!",
  ["_CeruleanCityCooltrainerMText"] = "¿También eres\nentrenador?\11Recoger, luchar,\11¡qué vida tan\11dura la nuestra!",
  ["_CeruleanCityGuardText"] = "A esta gente le\nhan robado.\12¡Seguro que el\nTEAM ROCKET tiene\11alguna relación\11con este \11atroz crimen!\12¡Hasta nuestra\nPOLICÍA tiene\11problemas con\11los ROCKET!",
  ["_CeruleanCityGymSign"] = "LÍDER del GIMNASIO\nPOKéMON de la\11CIUDAD CELESTE:\11MISTY\12¡La sirena\ndistorsionada!",
  ["_CeruleanCityRivalDefeatedText"] = "¡Oye!\n¡Tranquilo!\11¡Ya has ganado!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: ¿Sabes\nqué me pasó?\12¡Estuve con BILL\ny conseguí que me\11enseñara sus\11raros POKéMON!\12¡Y eso añadió\nmuchas páginas\11a mi POKéDEX!\12¡Por algo BILL es\nmundialmente\11conocido como\11POKéMANÍACO!\12¡Él inventó el\nSistema de\11Almacenamiento\11de POKéMON\11para PC!\12¡Como estás\nusando su sistema\11dale las gracias!\12¡En fin, mejor\nque me vaya!\11¡Hasta luego!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: ¡Hola\n{PLAYER}!\12¿Sigues avanzando\npenosamente?\12¡Por aquí todo va\ngenial! ¡Atrapé\11un montón de\11inteligentes y\11fuertes POKéMON!\12¡Vale {PLAYER},\nveamos qué has\11atrapado!",
  ["_CeruleanCityRivalVictoryText"] = "¡Je!\n¡Soy demasiado\11genial para ti!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\12¡Mejor que me\nvaya! ¡Adiós!",
  ["_CeruleanCityRocketIGiveUpText"] = "¡Alto!\n¡Me rindo!\11¡Me iré\11tranquilamente!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "¡Vale! ¡Devolveré\nla MT que robé!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "¡{PLAYER} recuperó\nla MT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "¡Hazle sitio\na esto!\12¡No puedo irme\nhasta dártelo!",
  ["_CeruleanCityRocketText"] = "¡Oye! ¡Fuera de\naquí! ¡Esto no\11te pertenece!\11¿Quién? ¿Yo?\12¡Soy un inocente\npeatón! ¿Es que\11no me crees?",
  ["_CeruleanCitySignText"] = "¡CIUDAD CELESTE!\n¡Una misteriosa\11aura azulada la\11rodea!",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ignoró\nlas órdenes...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO está\nholgazaneando...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO se\ndurmió...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO se\nalejó...",
  ["_CeruleanCitySuperNerd1Text"] = "Ese arbusto que\nhay delante de\11la tienda me\11impide pasar.\12Debería poder\nesquivarlo.",
  ["_CeruleanCitySuperNerd2Text"] = "¿Estás haciendo\nuna enciclopedia\11de los POKéMON?\11¡Qué increíble!",
  ["_CeruleanCitySuperNerd3Text"] = "¡Ésta es la CUEVA\nCELESTE! ¡En ella\11viven unos\11POKéMON\11súper fuertes!\12¡Sólo puede\nentrar el campeón\11de la LIGA\11POKéMON!",
  ["_CeruleanCityTrainerTipsText"] = "PISTAS ENTRENADOR\12Pulsar el botón B\ndurante la\11evolución\11cancelará todo\11el proceso.",
  ["_CeruleanGymAfterBattleText1"] = "Tienes que luchar\ncontra otros\11entrenadores para\11saber lo bueno\11que eres.",
  ["_CeruleanGymAfterBattleText2"] = "¡MISTY seguirá\nmejorando!\12¡Y no perderá con\nalguien como tú!",
  ["_CeruleanGymBattleText1"] = "¡Soy demasiado\nbuena para ti!\12¡MISTY puede\nesperar!",
  ["_CeruleanGymBattleText2"] = "¡Splash!\12¡Soy el primero!\n¡Al ataque!",
  ["_CeruleanGymEndBattleText1"] = "\n¡Me machacaste!",
  ["_CeruleanGymEndBattleText2"] = "¡No\npuede ser!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "¡Ganaste a MISTY!\n¿Qué decirte?\12¡Tú y yo formamos\nun equipo súper\11fuerte!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "¡Hola,\nposible campeón!\12¡Un consejo!\12¡La LÍDER, MISTY,\nes profesional y\11usa POKéMON\11acuáticos!\12¡Puedes absorber\ntoda su agua con\11los POKéMON\11del tipo-planta!\12¡O atrápalos con\nla electricidad!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "¡La MEDALLA\nCASCADA obligará\11a todos los\11POKéMON por\11debajo del nivel\v30 a obedecer!\12¡Incluidos los\nforasteros!\12¡Y podrás usar\nCORTAR siempre\11que quieras!\12¡Puedes CORTAR\npequeños arbustos\11para abrir\11nuevos caminos!\12¡Y te daré mi\nMT favorita!",
  ["_CeruleanGymMistyPreBattleText"] = "¡Hola! ¡Tú eres\nnuevo por aquí!\12¡Los entrenadores\nprofesionales\11deben tener una\11estrategia para\11sus POKéMON!\12¿Qué táctica\nsigues tú para\11atrapar a los\11POKéMON?\12¡Mi táctica es la\nofensiva total\11con los POKéMON\11del tipo-agua!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "¡Uauuu!\n¡Eres demasiado!\12¡Muy bien!\12¡Toma la MEDALLA\nCASCADA para que\11todos sepan que\11me ganaste!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "¡{PLAYER} obtiene\nla MT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "¡La MT11 enseña\nel RAYO BURBUJA!\12¡Úsala con los\nPOKéMON de agua!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "¡Mejor que le\nhagas sitio!",
  ["_CeruleanMartCooltrainerFText"] = "¿Has visto algún\nCARAMELO RARO?\12¡Dicen que un\nPOKéMON subirá\11un nivel\11si se lo come!",
  ["_CeruleanMartCooltrainerMText"] = "Usa el REPELENTE\npara evitar a los\11bichos y a los\11POKéMON débiles.\12¡Pon a tu POKéMON\nmás fuerte el\11primero de la\11lista para\11conseguir mejores\11resultados!",
  ["_CeruleanPokecenterGentlemanText"] = "¿Has oído hablar\nde BILL?\12¡Dicen que es un\nPOKéMANÍACO!\12Pero yo creo que\nla gente le tiene\11mucha envidia.\12¿Quién no querría\npresumir de sus\11POKéMON?",
  ["_CeruleanPokecenterGuyText"] = "¡BILL tiene\nmuchísimos\11POKéMON!\12¡Y algunos son\nmuy raros!",
  ["_CeruleanPokecenterSuperNerdText"] = "¡Ese BILL!\12¡Dicen que haría\nlo que fuera para\11conseguir raros\11POKéMON!",
  ["_CeruleanTradeHouseGrannyText"] = "A mi marido le\ngusta cambiar\11POKéMON.\12Si eres un\ncoleccionista,\11¿podrías cambiar\11con él?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "¡Esos malditos\nROCKET!\12¡Mira lo que\nhicieron aquí!\12¡Robaron una MT\npara enseñar a\11los POKéMON cómo\11EXCAVAR hoyos!\12¡Y eso me trajo\nmuchos problemas!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "¡Lo perdido\nperdido está!\12¡Y decidí enseñar\na DIGLETT cómo\11EXCAVAR sin\11tener una MT!",
  ["_CeruleanTrashedHouseGirlText"] = "¡El TEAM ROCKET\nestará intentando\11EXCAVAR su camino\11de maldades!",
  ["_CeruleanTrashedHouseWallHoleText"] = "¡El TEAM ROCKET\nabrió una nueva\11salida!",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: ¡{PLAYER}!\12¡Sabes que tu\nvictoria no fue\11debida sólo a\11ti!\12¡El vínculo que\nmantienes con tus\11POKéMON es\11maravilloso!\12¡{PLAYER}!\n¡Ven conmigo!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: ¡Ganaste!\n¡Enhorabuena!\11¡Eres el nuevo\11campeón de la\11LIGA POKéMON!\12¡Has crecido\ntanto desde que\11te fuiste con\11{RAM:wNameBuffer}!\12¡{PLAYER}, ya\neres mayor!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: ¡{RIVAL}!\n¡Estoy desolado!\12¡Vine en cuanto\nsupe que habías\11derrotado al ALTO\11MANDO!\12¡Pero cuando\nllegué aquí,\11ya habías sido\11derrotado!\12¡{RIVAL}!\n¿Entiendes por\11qué has perdido?\12¡Olvidaste tratar\na tus POKéMON\11con cariño y\11confianza!\12¡Y sin ellos,\njamás volverás a\11ser un campeón!",
  ["_ChampionsRoomOakText"] = "OAK: ¡{PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "¿Qué? ¿Cómo\nhe podido perder?\12He entrenado a\nmis POKéMON a\11la perfección.\12¡Maldición! ¡Eres\nel nuevo campeón\11de la LIGA\11POKéMON!\12Aunque no me\nguste admitirlo.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: ¡Hola!\12¡Estaba deseando\nverte {PLAYER}!\12¡Mi rival debería\nser fuerte para\11poder mantenerme\11en forma!\12¡Utilizando mi\nPOKéDEX, he\11buscado los\11POKéMON más\11fuertes!\12¡Y he creado\nvarios equipos\11que derrotarían\11a cualquier tipo\11de POKéMON!\12¡Y ahora!\12¡Yo soy el\ncampeón de la\11LIGA POKéMON!\12¡{PLAYER}!\n¿Sabes lo que\11significa eso?\12¡Te lo diré!\12¡Yo soy el mejor\nentrenador\11del mundo!",
  ["_ChanseyDexEntry"] = "Un raro y evasivo\nPOKéMON que,\nsegún dicen, trae\12la felicidad a\naquellos que lo\natrapan",
  ["_ChargeMoveEffectText"] = "¡{USER}",
  ["_CharizardDexEntry"] = "Escupe fuego tan\ncaliente que\nfunde las rocas.\12Causa incendios\nforestales\nsin querer",
  ["_CharmanderDexEntry"] = "Prefiere los\nsitios calientes.\nDicen que cuando\12llueve sale vapor\nde la punta\nde su cola",
  ["_CharmeleonDexEntry"] = "Cuando balancea\nsu ardiente cola,\neleva la\12temperatura a\nniveles muy\naltos",
  ["_ChooseABoxText"] = "Elige una CAJA\nde POKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "¡El FUEGO es lo\nmáximo en la\11técnica de las\11quemaduras!\12¡No lo malgastes\ncon los POKéMON\11acuáticos!",
  ["_CinnabarGymBlainePreBattleText"] = "¡Ja!\12¡Soy BLAINE!\n¡LÍDER del\11GIMNASIO de la\11CIUDAD CANELA!\12¡Mis feroces\nPOKéMON\11quemarán a\11todo aquel que\11me desafíe!\12¡Ja! ¡Mejor que\ntengas el\11ANTIQUEMADURAS!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "¡Me has\nmachacado!\12¡Has ganado la\nMEDALLA-VOLCÁN!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\12¡La MT38 incluye\nla LLAMARADA!\12¡Enseña este\nataque a los\11POKéMON del\11tipo-fuego!\12¡CHARMELEON o\nPONYTA serían las\11mejores apuestas!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "¡Hazle sitio a\nmi regalo!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "¡Ja!\12¡La MEDALLA-\nVOLCÁN mejora\11las habilidades\11ESPECIALES de\11tus POKéMON!\12¡Mira, también\nte daré esto!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "¡{PLAYER}, ganaste\na esa antorcha\11de fuego!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "¡Hola, posible\ncampeón!\12¡BLAINE es un\nprofesional de\11los POKéMON\11del fuego!\12¡Apaga con agua\nsus ánimos!\12¡Mejor que lleves\nANTIQUEMADURAS!",
  ["_CinnabarGymQuizCorrectText"] = "¡Respuesta\ncorrecta!\12¡Adelante!",
  ["_CinnabarGymQuizIncorrectText"] = "¡Mal! ¡Lo siento!",
  ["_CinnabarGymQuizIntroText"] = "¡POKéAcertijo!\12¡Responde bien y\nabrirás la puerta\11a la siguiente\11habitación!\12¡Responde mal y\nlucharás contra\11un entrenador!\12Si prefieres\nguardar tus\11POKéMON para\11el LÍDER del\11GIMNASIO...\12¡Hazlo bien!\n¡Vamos allá!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Fuego, o para ser\nmás preciso,\11combustión...\12¡Bla, bla, bla,\nbla!...",
