  ["_OakLabEmailText"] = "¡Aquí hay un\nmensaje e-mail!\12...\12¡Aviso a todos\nlos entrenadores\11de POKéMON!\12¡Los entrenadores\nde élite de la\11LIGA POKéMON\11están listos\11para desafiaros\11a todos!\12¡Traed a vuestros\nmejores POKéMON\11y descubrid\11vuestra \11puntuación como\11entrenadores!\12CG de la LIGA\nPOKéMON\11MESETA AÑIL\12PD: ¡PROF. OAK,\nvisítenos por\11favor!...",
  ["_OakSpeechText1"] = "¡Hola a todos!\n¡Bienvenidos al\11mundo de POKéMON!\12¡Me llamo OAK!\n¡Pero la gente me\11llama el PROFESOR\11POKéMON!",
  ["_OakSpeechText2A"] = "¡Este mundo está\nhabitado por unas\11criaturas\11llamadas POKéMON!",
  ["_OakSpeechText2B"] = "\12Para algunos, los\nPOKéMON son\11mascotas. Pero\11otros los usan\11para pelear.\12En cuanto a mí...\12Estudio a los\nPOKéMON como\11profesión.",
  ["_OakSpeechText3"] = "¡{PLAYER}!\12¡Tu propia\nleyenda POKéMON\11está a punto de\11comenzar!\12¡Te espera un\nmundo de sueños\11y aventuras con\11los POKéMON!\11¡Adelante!",
  ["_OaksAideComeBackText"] = "¡Ah! Ya veo.\12Cuando tengas {NUM:hOaksAideRequirement, 1, 3}\ntipos, vuelve a\11por {RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "¡{PLAYER} obtuvo\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "¡Bien! ¡Has\nlogrado {NUM:hOaksAideNumMonsOwned, 1, 3} tipos \11de POKéMON!\11¡Enhorabuena!\12¡Aquí tienes!",
  ["_OaksAideHiText"] = "¡Hola! ¿Te\nacuerdas de mí?\11¡Soy AYUDANTE\11del PROF. OAK!\12¡Si atrapaste {NUM:hOaksAideRequirement, 1, 3}\ntipos de POKéMON,\11se supone que\11debería darte\11{RAM:wOaksAideRewardItemName}!\12¡Bien {PLAYER}!\n¿Atrapaste por lo\11menos {NUM:hOaksAideRequirement, 1, 3} tipos\11de POKéMON?",
  ["_OaksAideNoRoomText"] = "¡Oh! Ya veo que\nno tienes\11sitio para\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Veamos...\n¡Oh! ¡Atrapaste\11solamente {NUM:hOaksAideNumMonsOwned, 1, 3}\11tipos de POKéMON!\12Necesitas {NUM:hOaksAideRequirement, 1, 3}\ntipos si quieres\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "¡El PROF. OAK es\nun experto en\11POKéMON!\12¡Es admirado por\nmuchos de los\11entrenadores de\11POKéMON!",
  ["_OaksLabGivePokeballsExplanationText"] = "\12Cuando aparezca\nun POKéMON\11salvaje, lucha\11contra él.\12¡Lánzale una\nPOKé BALL para\ncapturarlo!\12¡Pero esto no\nsiempre funciona!\12¡Un POKéMON\nsano podría huir!\11¡También cuenta\11la suerte!",
  ["_OaksLabLastMonText"] = "¡Ése es el último\nPOKéMON del\11PROF. OAK!",
  ["_OaksLabMonEnergeticText"] = "¡Este POKéMON es\nmuy energético!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Ven a verme\nde vez en cuando.\12¡Tenme informado\nsobre cómo te va\11con tu POKéDEX!",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: ¡{PLAYER}!\12¿Cómo va tu\nPOKéMON?\12¡Creo que te\nquiere mucho!\12¡Pareces ser\nmuy hábil como\11entrenador de\11POKéMON!\12¿Qué? ¿Tienes\nalgo para mí?\12{PLAYER} entregó\nel CORREO de OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK : ¡Encantado\nde verte! ¿Cómo\11va tu POKéDEX?\11¡Déjame que le\11eche un vistazo!",
