  ["_RockTunnel1FHiker2BattleText"] = "Mmm. Puede que me\nhaya perdido...",
  ["_RockTunnel1FHiker2EndBattleText"] = "\n¡Tranquilo!\11¿Qué hago?\11¿Por dónde salgo?",
