  ["_RockTunnelB1FHiker1AfterBattleText"] = "¡Prefiero la\nfuerza porque no\11me gusta pensar!",
  ["_RockTunnelB1FHiker1BattleText"] = "¡Jajaja! ¿Crees\npoder ganarme?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "¡Uups!\nNivel muscular:\11¡Cero!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "En las montañas\nsuele haber\11POKéMON del\11tipo-roca.",
  ["_RockTunnelB1FHiker2BattleText"] = "¡Mis técnicas de\nPOKéMON te\11harán llorar!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "\n¡Me rindo!\11¡Tus técnicas\11son mejores!",
