  ["_RocketHideoutB1FRocket5EndBattleText"] = "\n¿Por qué...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "El CG del TEAM\nROCKET tiene 4\11sótanos. ¿Podrás\11llegar al JEFE?",
