  ["_RocketHideoutB2FRocketEndBattleText"] = "\n¡Me rindo!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "¿El SCOPE SILPH?\nLa máquina que\11robó el JEFE.\11Debe de estar\11por aquí.",
  ["_RocketHideoutB3FRocket1BattleText"] = "¡Deja de meterte\nen los asuntos\11del TEAM ROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "¡Uff!\n¡Me tumbaron!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Ya veo que has\nentrenado a tus\11POKéMON con\11mucho cuidado.\12¡Un niño como tú\njamás entendería\11cuáles son mis\11planes!\12¡En esta ocasión\nte dejaré pasar!\12Espero que nos\nvolvamos a ver.",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "¡Mmm! ¡Estoy muy\nimpresionado de\11que hayas llegado\11hasta aquí!",
