  ["_RocketHideoutB4FRocket2EndBattleText"] = "¡Ayayay!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "¡Oh no! ¡He\nperdido la LLAVE\11del ASCENSOR!",
