  ["_Route10CooltrainerF1EndBattleText"] = "\n¡Volví a perder!",
  ["_Route10CooltrainerF2AfterBattleText"] = "¡Estos POKéMON\nson tan robustos!\11¡Debería haber\11alguno rosa con\11bonitas flores!",
