  ["_Route12CooltrainerMEndBattleText"] = "\n¡Auuuu!",
  ["_Route12Fisher1AfterBattleText"] = "¡Alto! ¡Mi sedal\nestá enganchado!",
  ["_Route12Fisher1BattleText"] = "¡Bien! ¡Ha\npicado algo!",
  ["_Route12Fisher1EndBattleText"] = "\n¡Bah! ¡Era muy\11pequeñajo!",
