  ["_Route12Fisher4AfterBattleText"] = "Está bien.\nPerder ya no\11me importa.",
  ["_Route12Fisher4BattleText"] = "¡Preferiría estar\ntrabajando!",
  ["_Route12Fisher4EndBattleText"] = "No\nes fácil...",
  ["_Route12Fisher5AfterBattleText"] = "¡Es fácil pescar\nMAGIKARP, son\11tan débiles!",
