  ["_Route12SnorlaxText"] = "¡Un POKéMON\ndormido bloquea\11el camino!",
  ["_Route12SnorlaxWokeUpText"] = "¡SNORLAX se\ndespertó!\12¡Se enfadó mucho\ny ataca furioso!",
  ["_Route12SportFishingSignText"] = "ZONA DE PESCA",
