  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "¡Oh no!\12¡Tenía un regalo\npara ti, pero no\11tienes sitio!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "¡Genial! ¡Me\ngusta tu estilo!\12¡Toma esto y\npesca, jovencito!\12¡{PLAYER} obtuvo\n{RAM:wStringBuffer}!",
