  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "¡Hola,\n{PLAYER}!\12¡Utiliza la SÚPER\nCAÑA en todo tipo\11de aguas! Puedes\11pescar diferentes\11tipos de POKéMON.\12¡Pesca siempre\nque puedas!",
  ["_Route13Beauty1AfterBattleText"] = "¿Cuál es más\nfuerte, un\11POKéMON femenino\11o masculino?",
