  ["_Route9CooltrainerM1EndBattleText"] = "\n¡Esto se acabó!",
  ["_Route9CooltrainerM2AfterBattleText"] = "¿Vas a ir también\nal TÚNEL ROCA?",
  ["_Route9CooltrainerM2BattleText"] = "¡Tomaré el TÚNEL\nROCA para ir al\11PUEBLO LAVANDA!",
  ["_Route9CooltrainerM2EndBattleText"] = "\n¡Soy muy\11malo! ¡Buaaa!",
  ["_Route9Hiker1AfterBattleText"] = "¡Debes ser muy\nvaliente para\11desafiarme!",
  ["_Route9Hiker1BattleText"] = "¡Jaja! ¡Qué bien!\n¡Me estaba\11aburriendo!",
  ["_Route9Hiker1EndBattleText"] = "\n¡No te detengas,\11sigue, sigue!\12Espera. ¡No tengo\nmás POKéMON!",
  ["_Route9Hiker2AfterBattleText"] = "¡Jajaja! ¡Los\nniños deben ser\11duros!",
  ["_Route9Hiker2BattleText"] = "¡Jaja!\n¡No es que seas\11muy duro!",
  ["_Route9Hiker2EndBattleText"] = "¿Qué\nes eso?",
  ["_Route9Hiker3AfterBattleText"] = "¡Jajaja!\n¡Los más fuertes\11siempre reímos!",
  ["_Route9Hiker3BattleText"] = "¡Jajajaja!\n¡Vamos pequeñajo!",
  ["_Route9Hiker3EndBattleText"] = "\n¡Jajajaja!\11¡Me has ganado!",
  ["_Route9SignText"] = "RUTA 9:\nCIUDAD CELESTE -\11TÚNEL ROCA",
  ["_Route9Youngster1AfterBattleText"] = "Tengo que recoger\nalgo que no sea\11bichos para ser\11más fuerte...",
  ["_Route9Youngster1BattleText"] = "¡Madrugo todos\nlos días para\11cuidar a mis\11POKéMON del\11tipo-capullo!",
  ["_Route9Youngster1EndBattleText"] = "¿QUÉ?\12¡Qué gran pérdida\nde tiempo!",
  ["_Route9Youngster2AfterBattleText"] = "¿No te gustan los\nbichos POKéMON?\11¡Pues inféctame!",
  ["_Route9Youngster2BattleText"] = "¡Adelante mi\nsúper bicho\11POKéMON!",
  ["_Route9Youngster2EndBattleText"] = "Mis\nbichos...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "¡Dañaste a mis\npobres POKéMON!\12¡¡¡Y exijo que\nlos cures en\11un CENTRO\11POKéMON!!!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "¡Recogí estos\nPOKéMON por\11todo el mundo!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "¡Oh no!\n¡Viajé por todo\11el mundo\11sólo por ellos!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "¡Deberías\nportarte bien\11con los amigos!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "¡Viajo solo!\12¡Mis POKéMON\nson mis únicos\11amigos!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "¡Oh!\n¡Mis amigos!",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "¡Me gustaría que\nme dejaras solo!\12¡¡Fuera de aquí!!",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "¡Oye tú, mocoso!\n¿Cómo te atreves\11a entrar aquí?",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "¡Oye!\n¡¡Eres un\11niño muy malo!!",
  ["_SSAnne1FRoomsGentleman3Text"] = "¡Ssh! ¡Soy agente\nde POLICÍA!\12¡Estoy siguiendo\nla pista del\11TEAM ROCKET!",
  ["_SSAnne1FRoomsGirl1Text"] = "¡Camarero, me\ngustaría tomar\11una tarta de\11cerezas!",
  ["_SSAnne1FRoomsGirl2Text"] = "¡Viajamos en\ncrucero por\11todo el mundo!",
  ["_SSAnne1FRoomsLittleGirlText"] = "¡Siempre viajo\ncon WIGGLYTUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "¡Los cruceros son\ntan elegantes y\11acogedores!",
  ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: ¡Wig\nTuuuf, Tuuuf!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Seamos amigos,\n¿vale?\12¡Y así podremos\nintercambiar\11POKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "¡Me gustan los\nPOKéMON!\11¿Y a ti?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "¡Guauu!\n¡Eres estupendo!",
  ["_SSAnne1FSailorText"] = "¡Los pasajeros\nse están\11impacientando!\12¡Los que están\nmás aburridos\11podrían retarte!",
  ["_SSAnne1FWaiterText"] = "¡Bonjour! ¡Soy\nel camarero de\11este barco!\12¡Encantado de\nservirte en todo\11lo que quieras!\12¡Pareces del tipo\nfuerte y callado!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Decían\nque había un\11maestro del CORTE\11a bordo.\12¡Pero sólo era\nun viejo mareado!\12¡Sin embargo, la\ntécnica del CORTE\11es muy útil!\12¡Deberías ir\na verle!\11¡Hasta luego!",
  ["_SSAnne2FRivalDefeatedText"] = "¡Vaya!\12¡Parece que has\nentrenado bien\11a tus POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}:\n¡Bonjour {PLAYER}!\12¡Ya sabía yo\nque te vería\11por aquí!\12¿{PLAYER}, de\nverdad fuiste\11invitado?\12¿Y qué tal va\ntu POKéDEX?\12¡Ya tengo 40\nPOKéMON,\11chaval!\12¡Están por todas\npartes!\12¡Adéntrate en\nlas zonas de\11hierba alta!",
  ["_SSAnne2FRivalVictoryText"] = "¡{PLAYER}!\n¿Estás mareado?\12¡Pues deberías\nponerte en forma,\11amigo!",
  ["_SSAnne2FRoomsBeautyText"] = "¡Dicen que hay\nmucha gente\11que se marea!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "¡El CAPITÁN\nparecía muy\11mareado y pálido!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "¡Oh! ¡Adoro a\ntus fuertes\11POKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Nunca te había\nvisto en la\11fiesta.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "¡Oye!\n¡¡¡No te pongas\11nervioso!!!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "¿Una fiesta?\12La fiesta del\ncrucero debe de\11haber terminado.",
  ["_SSAnne2FRoomsFisherBattleText"] = "¡Mira lo que\nhe pescado!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "\n¡Estoy acabado!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "¡Hace 15 años, yo\nhabría ganado!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "¡Competir contra\nlos jóvenes me\11mantiene joven!",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "¡Buena\npelea! ¡Vuelvo a\11sentirme joven!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "¡Prefiero a\nlos POKéMON\11fuertes y raros!",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "¿Qué prefieres,\nun POKéMON fuerte\11o uno raro?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "¡Debo\nfelicitarte!",
  ["_SSAnne2FRoomsGentleman3Text"] = "¡Durante todos\nmis viajes jamás\11había visto a un\11POKéMON que\11durmiera tanto!\12¡Era algo\nasí!...",
  ["_SSAnne2FRoomsGentleman4Text"] = "¡Ah sí! ¡Vi a\nunos POKéMON\11transportando a\11gente por el\11agua!",
  ["_SSAnne2FRoomsGentleman5Text"] = "¿Has ido a la\nZONA DE SAFARI\11en la CIUDAD\11FUCSIA?\12¡Había muchos\ntipos raros de\11POKéMON!",
  ["_SSAnne2FRoomsGrampsText"] = "Los POKéMON\npueden CORTAR\11pequeños\11arbustos.",
  ["_SSAnne2FRoomsLittleBoyText"] = "¡Mi padre y yo\npensamos que la\11ZONA DE SAFARI\11es genial!",
  ["_SSAnne2FWaiterText"] = "¡Este lujoso\nbarco es para\11los entrenadores!\12¡En cada puerto\ncelebramos una\11fiesta para los\11entrenadores!",
  ["_SSAnne3FSailorText"] = "¡Nuestro CAPITÁN\nes un maestro de\11la esgrima!\12¡Y hasta enseña\na los POKéMON\11la técnica del\11CORTE!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "¡Yo también te\niba a hacer mi\11ayudante!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "¡Hola forastero!\n¡Para y hablemos!\12¡Todos mis\nPOKéMON vienen\11del mar!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "\n¡Maldición!\11¡Dejé que se me\11escapara ése!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOKE: ¡Cho!\n¡Choke Cho!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "¡Ajá! ¿Quieres\nser marinero?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "¡Ya sabes lo que\ndicen sobre los\11marineros y\11las peleas!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "\n¡Has peleado muy\11bien, compañero!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "¿Viste al GURÚ\nde los PESCADORES\11en CIUDAD CARMÍN?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "¡Está en juego mi\nfama de marinero!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "\n¡Tu espíritu\11me hundió!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "¡Pescamos a\ntodos nuestros\11POKéMON\11en alta mar!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "¡Los marineros\ntambién tenemos\11POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "¡Eres\nbastante bueno!",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "Los POKéMON del\nmar viven en las\11profundidades.\11¡Necesitarás\11una CAÑA!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "¡Me gustan los\nniños activos\11como tú!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "¡Argh!\n¡He perdido!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "A veces, algunas\nmedusas caen\11en el barco.",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "¡Como pierdas\ncaminarás por el\11tablón, amigo!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "¡Argh!\n¡Derrotado\11por un niño!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "¡Mi amigo,\nMACHOKE, es\11súper fuerte!\12¡Tiene tanta\nFUERZA que puede\11mover hasta\11grandes rocas!",
  ["_SSAnneBowCooltrainerMText"] = "¡Uff! Me siento\nfatal...\12He salido a\ntomar el aire.",
  ["_SSAnneBowSailor1Text"] = "¡Limpiar las\ncubiertas es un\11trabajo duro!",
  ["_SSAnneBowSailor2AfterBattleText"] = "¿Cuántos tipos\nde POKéMON\11crees que hay?",
  ["_SSAnneBowSailor2BattleText"] = "¡Eh, amigo!\12¡Bailemos una\njota!",
  ["_SSAnneBowSailor2EndBattleText"] = "¡Eres\nimpresionante!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mi papá decía\nque hay 100 tipos\11de POKéMON. Pero\11yo creo que\11hay más.",
  ["_SSAnneBowSailor3BattleText"] = "¡Ah del barco!\n¿Estás mareado?",
  ["_SSAnneBowSailor3EndBattleText"] = "¡No\ntuve cuidado!",
  ["_SSAnneBowSuperNerdText"] = "¡Se acabó la\nfiesta! ¡El barco\11zarpará pronto!",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "¡Oh no! ¡No\ntienes sitio\11para esto!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITÁN: ¡Uff!\n¡Gracias! Ya me\11siento mucho\11mejor...\12¿Quieres ver mi\ntécnica de\11CORTAR?\12Te la mostraría\nsi no estuviera\11tan mareado.\12¡Ya sé!\n¡Toma esto!\12¡Enséñasela a tu\nPOKéMON y en\11breve estará\11CORTANDO!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITÁN: ¡Bien!\12¡Ahora que ya no\nestoy mareado,\11creo que\11deberíamos irnos!",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "¡{PLAYER} obtiene\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITÁN: ¡Puajj!\nMe siento fatal.\11Me he mareado...\12¡{PLAYER} le dio\nun masaje al\11CAPITÁN!\12(Scratch)...\n(Scratch)...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Comó combatir el\nMareo...\11¡El CAPITÁN está\11leyendo esto!",
  ["_SSAnneCaptainsRoomTrashText"] = "¡Puaj! ¡No debería\nhaber mirado!",
  ["_SSAnneKitchenCook1Text"] = "¡Hola, pequeñajo!\n¡Ahora estamos\11ocupados!\11¡Fuera de aquí!",
  ["_SSAnneKitchenCook2Text"] = "Vi una bola muy\nrara en la\11basura.",
  ["_SSAnneKitchenCook3Text"] = "¡Estoy tan\nocupado que me\11estoy mareando!",
  ["_SSAnneKitchenCook4Text"] = "¿Por qué?\n¿Por qué yo?\12¡Me paso todo\nel día pelando\11patatas!",
  ["_SSAnneKitchenCook5Text"] = "¿Has oído hablar\nde SNORLAX?\12¡Se pasa todo el\ndía comiendo y\11durmiendo!",
  ["_SSAnneKitchenCook6Text"] = "Sniff...sniff...\12Yo sólo pelo\ncebollas...\11Sniff...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "¡Ejem! ¡Por algo\nsoy el CHEF!\12El menú es:",
  ["_SSTicketNoRoomText"] = "Llevas demasiadas\ncosas, chico.",
  ["_SSTicketReceivedText"] = "¡{PLAYER} obtuvo\n{RAM:wStringBuffer}!",
