  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: ¿Adónde\nfue mi amigo\11ERIC?",
  ["_SafariZoneCenterRestHouseScientistText"] = "¡Estoy atrapando\nPOKéMON para\11llevarlos a casa\11como regalos!",
  ["_SafariZoneCenterRestHouseSignText"] = "CASA DE REPOSO",
