  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Devuelve las\nSAFARI BALL que\11te sobren.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "¡Bienvenido a la\nZONA del SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "¡Son ¥{NUM:wPriceTemp, $c3},\npor favor!\12Aquí sólo usamos\ncierto tipo de\11POKé BALL.\12¡{PLAYER} obtuvo\n30 SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "¡Por sólo 500$,\npodrás atrapar a\11todos los POKéMON\11que quieras en\11el parque!\12¿Te gustaría\nunirte a la caza?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "¡Hola! ¿Es tu\nprimera vez aquí?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "La ZONA-SAFARI\nincluye 4 áreas.\12Cada zona tiene\ndiferentes tipos\11de POKéMON. ¡Usa\11las SAFARI BALL\11para atraparlos!\12¡Si agotas el\ntiempo o las\11SAFARI BALL, el\11juego se dará\11por terminado!\12¡Antes de ir,\nabre una nueva\11CAJA POKéMON\11y tendrás más\11sitio para nuevos\11POKéMON!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "¡Perdona, vienes\nmucho por aquí!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "¡Mi EEVEE se\ntransformó en un\11FLAREON!\12¡Pero el EEVEE de\nun amigo se\11transformó en\11un VAPOREON!\11¿Por qué?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Dirígete al área\nmás profunda del\11SAFARI. ¡Ganarás\11un premio!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Puedes quedarte\ncon cualquier\11objeto encontrado\11en esta zona.\12¡Pero te quedarás\nsin tiempo si\11intentas coger\11todos a la vez!",
  ["_SafariZoneNorthRestHouseSignText"] = "CASA DE REPOSO",
  ["_SafariZoneNorthSignText"] = "ÁREA 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "PISTAS ENTRENADOR\12¡La CASA SECRETA\nsigue estando\11justo delante!",
  ["_SafariZoneNorthTrainerTips2Text"] = "PISTAS ENTRENADOR\12¡Los POKéMON\nse ocultan entre\11la alta hierba!\12Zigzaguea por\nzonas de hierba\11para que salgan.",
  ["_SafariZoneNorthTrainerTips3Text"] = "PISTAS ENTRENADOR\12¡Encuentra la\nCASA SECRETA y\11ganarás una MO!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "¡La MO03 es SURF!\12¡Un POKéMON\npodrá llevarte\11por el agua!\12¡Y esta MO puede\nser utilizada una\11y otra vez!\12¡Tienes muchísima\nsuerte! ¡Eres el\11ganador de este\11fabuloso premio!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "¡No tienes sitio\npara este premio\11tan fabuloso!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "¡{PLAYER} recibió\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "¡Ah! ¡Por fin!\12¡Eres el primero\nque llega a la\11CASA SECRETA!\12Estaba empezando\na preocuparme\11que nadie ganara\11nuestro premio.\12¡Enhorabuena!\n¡Eres el ganador!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVISO\12Encuentra los\nDIENTES DE ORO\11perdidos del\11GUARDA del\11SAFARI. Están\11por aquí.\12¡Se ofrece\nrecompensa!\11Contactar con\11el GUARDA.",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Utilizar CEBO te\npermitirá atrapar\11más fácilmente a\11los POKéMON.",
  ["_SafariZoneWestRestHouseScientistText"] = "Tirar PIEDRAS a\nlos POKéMON\11podría hacerles\11huir, pero\11serán más fáciles\11de atrapar.",
  ["_SafariZoneWestRestHouseSignText"] = "CASA DE REPOSO",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Caminé mucho,\npero no he visto\11a los POKéMON\11que quería.",
  ["_SafariZoneWestSignText"] = "ZONA 3\nESTE: ÁREA\11CENTRAL",
  ["_SafariZoneWestTrainerTipsText"] = "PISTAS ENTRENADOR\12¡Operación\nExploración\11de la Zona!\12¡La búsqueda de\nla CASA SECRETA!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO-KARATE",
  ["_SaffronCityGentlemanText"] = "Volé aquí en mi\nPIDGEOT cuando\11supe de SILPH.\12¿Ya se acabó?\nMe perdí toda\11la acción.",
  ["_SaffronCityGymSignText"] = "LÍDER del GIMNASIO\nPOKéMON de la\11CIUDAD AZAFRÁN:\11SABRINA\12¡Maestra de los\nPOKéMON\11psíquicos!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "CASA DEL\nSR. PSÍQUICO",
  ["_SaffronCityPidgeotText"] = "PIDGEOT: ¡Pid pid!",
  ["_SaffronCityPokecenterGuyText1"] = "¡Sería estupendo\nque el ALTO MANDO\11viniera y\11machacara al\11TEAM ROCKET!",
  ["_SaffronCityPokecenterGuyText2"] = "¡El TEAM ROCKET\nse ha ido! ¡Ahora\11podemos salir sin\11peligro! ¡Bien!",
  ["_SaffronCityRockerText"] = "Vi al JEFE ROCKET\nescapando del\11edificio SILPH.",
  ["_SaffronCityRocket1Text"] = "¿Qué quieres?\n¡Lárgate!",
  ["_SaffronCityRocket2Text"] = "¡El JEFE dice que\ninvadirá esta\11ciudad!",
  ["_SaffronCityRocket3Text"] = "¡Fuera del\ncamino!",
  ["_SaffronCityRocket4Text"] = "¡AZAFRÁN es del\nTEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "¡Ser malo me hace\nsentir tan vivo!",
  ["_SaffronCityRocket6Text"] = "¡Au! ¡Cuidado por\ndonde caminas!",
  ["_SaffronCityRocket7Text"] = "¡Con SILPH bajo\ncontrol, podemos\11explotar a los\11POKéMON de\11todo el mundo!",
  ["_SaffronCityRocket8Text"] = "Soy el guarda de\nseguridad.\12¡No permito\nentrar a chicos\11sospechosos!",
  ["_SaffronCityRocket9Text"] = "...\n(Ronquido)...\12¡Ja! ¡Está\ndurmiendo la\11siesta!",
  ["_SaffronCityScientistText"] = "¿Venciste tú solo\nal TEAM ROCKET?\11¡Qué increíble!",
  ["_SaffronCitySignText"] = "CIUDAD AZAFRÁN\nLa brillante y\11dorada tierra del\11comercio.",
  ["_SaffronCitySilphCoLatestProductSignText"] = "¡Lo último de\nSILPH!\12Lanzado para ser\ndecisivo...",
  ["_SaffronCitySilphCoSignText"] = "EDIFICIO-OFICINAS\nde SILPH S.A.",
  ["_SaffronCitySilphWorkerFText"] = "La gente puede\nregresar ahora a\11AZAFRÁN.",
  ["_SaffronCitySilphWorkerMText"] = "¡El TEAM ROCKET\nse ha marchado!\11¡Ahora podemos\11salir otra vez!",
  ["_SaffronCityTrainerTips1Text"] = "PISTAS ENTRENADOR\12CURA TOTAL cura\ntodo malestar,\11como el sueño y\11las quemaduras.\12Cuesta un poco\nmás, pero merece\11la pena.",
  ["_SaffronCityTrainerTips2Text"] = "PISTAS ENTRENADOR\12La nueva SÚPER\nBALL ofrece una\11mayor velocidad\11de captura.\12Pruébala con\nesos POKéMON\11tan difíciles de\11atrapar.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Estoy de guardia.\n¡Uauu! ¡Qué sed\11tengo!\12Espera. La ruta\nestá cerrada.",
  ["_SaffronGateGuardImParchedText"] = "¡Uauu, chico!\n¡Estoy sediento!\11...\11¿Eh? ¿Me das\11esa bebida? \11¡Gracias chaval!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "¡Oye! ¡Gracias\npor las bebidas!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\12...\nGlu glu...\11...\11(Trago)...\11Si quieres ir a\11CIUDAD AZAFRÁN...\11...\11Puedes pasar...\11¡Compartiré esto\11con los otros\11guardias!",
  ["_SaffronGymChanneler1AfterBattleText"] = "¡En una pelea de\niguales, ganará\11quien tenga más\11voluntad!\12¡Si quieres ganar\na SABRINA, piensa\11sólo en ganar!",
  ["_SaffronGymChanneler1BattleText"] = "¡SABRINA es más\njoven que yo,\11pero la respeto!",
  ["_SaffronGymChanneler1EndBattleText"] = "\n¡Vaya fallo!",
  ["_SaffronGymChanneler2AfterBattleText"] = "¡Debo enseñarles\nmejores técnicas\11a mis POKéMON!",
  ["_SaffronGymChanneler2BattleText"] = "Los POKéMON\nacaban teniendo\11el aspecto de sus\11entrenadores.\12¡Pues tus POKéMON\nparecen fuertes!",
  ["_SaffronGymChanneler2EndBattleText"] = "\n¡Lo sabía!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Sabía que esto\niba a pasar.",
  ["_SaffronGymChanneler3BattleText"] = "¡Tú y yo!\nNuestros POKéMON\11deben luchar.",
  ["_SaffronGymChanneler3EndBattleText"] = "\n¡Al final perdí!",
  ["_SaffronGymGuideBeatSabrinaText"] = "¿Poder mental?\12¡Si yo lo tuviera\nme haría rico en\11las tragaperras!",
  ["_SaffronGymGuideChampInMakingText"] = "¡Hola, posible\ncampeón!\12¡Los POKéMON\nde SABRINA usan\11el poder de la\11mente y no la\11fuerza!\12¡Los POKéMON\nguerreros son\11débiles contra\11los POKéMON\11psíquicos!\12¡Se debilitan\nantes de poderse\11preparar!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "¡Con la MEDALLA\nPANTANO, todo\11POKéMON con\11nivel inferior a\v70 te obedecerá!\12¡Los POKéMON más\nfuertes ignorarán\11tus órdenes en\11la batalla!\12¡No entrenes\ndemasiado a\11tus POKéMON!\12¡Espera, llévate\nesta MT!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "¡Todo el mundo\ntiene poderes\11mentales, pero la\11gente lo ignora!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "¡Estoy\nimpresionada!\11Acepto mi\11derrota.\12¡Admito que no\nfui lo bastante\11fuerte y perdí!\12¡Has ganado la\nMEDALLA del\11PANTANO!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "¡{PLAYER} obtiene\nla MT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "¡Tu mochila está\nllena de otros\11objetos!",
  ["_SaffronGymSabrinaText"] = "¡Tuve una visión\nde tu llegada!\12¡Tengo poderes\npsíquicos desde\11que era niña!\12Primero aprendí\na doblar cucharas\11con mi mente.\12¡Odio luchar, \npero si quieres\11puedo enseñarte\11mis poderes!",
  ["_SaffronGymYoungster1AfterBattleText"] = "¡Los POKéMON\npsíquicos temen\11sólo a los bichos\11y fantasmas!",
  ["_SaffronGymYoungster1BattleText"] = "¿Nuestro oculto\npoder te asusta?",
  ["_SaffronGymYoungster1EndBattleText"] = "¡Jamás lo\nhubiera pensado!",
  ["_SaffronGymYoungster2AfterBattleText"] = "¡SABRINA ganó al\nMAESTRO de KARATE\11de la puerta de\11al lado!",
  ["_SaffronGymYoungster2BattleText"] = "¡Sabes que sólo\ntu poder no es\11suficiente!",
  ["_SaffronGymYoungster2EndBattleText"] = "¡No me\nlo puedo creer!",
  ["_SaffronGymYoungster3AfterBattleText"] = "En la CIUDAD\nAZAFRÁN solía\11haber 2 GIMNASIOS\11POKéMON.\12¡El DOJO-KARATE\nde aquí al lado\11perdió su\11condición de\11GIMNASIO cuando\11los machacamos!",
  ["_SaffronGymYoungster3BattleText"] = "¡SABRINA es joven,\npero es nuestra\11LÍDER!\12¡No llegarás a\nella fácilmente!",
  ["_SaffronGymYoungster3EndBattleText"] = "¡No pude\nconcentrarme!",
  ["_SaffronGymYoungster4AfterBattleText"] = "¡Tienes razón!\n¡Usé la telepatía\11para leer tu\11mente!",
  ["_SaffronGymYoungster4BattleText"] = "¡El GIMNASIO\nPOKéMON de\11AZAFRÁN es famoso\11por sus médiums!\12¡Quieres ver a\nSABRINA!\11¡Lo sé!",
  ["_SaffronGymYoungster4EndBattleText"] = "¡Arrrgg!",
  ["_SaffronMartCooltrainerFText"] = "¡REVIVIR es caro,\npero revive a los\11POKéMON\11debilitados!",
  ["_SaffronMartSuperNerdText"] = "¡MÁX. REPEL dura\nmás que el SÚPER\11REPEL en cuanto\11a mantener lejos\11a los POKéMON\11débiles!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Gracias por\nescribir. ¡Espero\11verte pronto!\12¡Oye! ¡No mires\nmi carta!",
  ["_SaffronPidgeyHousePaperText"] = "Recibí MÁS PP\ncomo regalo.\12¡Sirve para\naumentar los PP\11de los ataques!",
  ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: ¡Pid pid!",
  ["_SaffronPidgeyHouseYoungsterText"] = "¡La COPIONA es\nmuy mona! ¡Le\11voy a dar una\11POKé MUÑECA!",
  ["_SaffronPokecenterBeautyText"] = "La velocidad de\ncrecimiento de\11los POKéMON\11varía de una\11especie a otra.",
  ["_SaffronPokecenterGentlemanText"] = "SILPH S.A. es muy\nfamosa. ¡Por eso\11el TEAM ROCKET\11tiene tanto\11interés en ella!",
  ["_SandshrewDexEntry"] = "Se oculta bajo\ntierra, en zonas\náridas y alejadas\12del agua. Sólo\nemerge para cazar\nsu comida",
  ["_SandslashDexEntry"] = "Ante el peligro\nse acurruca en un\nespinoso ovillo.\12De esta forma\npuede rodar para\natacar o escapar",
  ["_SaveOptionText"] = "En la pantalla\ndel MENÚ está la\11opción GUARDAR.",
  ["_SavingEnergyText"] = "¡{USER}\nguarda energía!",
  ["_ScaredText"] = "¡{RAM:wBattleMonNick} está\ntan asustado que\11no puede moverse!",
  ["_ScytherDexEntry"] = "Con una agilidad\ny velocidad tipo-\nninja, puede\12crear la ilusión\nde que hay más\nde uno",
  ["_SeadraDexEntry"] = "Puede nadar hacia\natrás moviendo\nrápidamente sus\12aletas pectorales\ny su robusta\ncola",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "¡Ar Tic!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "¡Las ROCAS pueden\ncambiar el flujo\11del agua!",
  ["_SeafoamIslandsB4FDangerSignText"] = "¡PELIGRO!\n¡Rápidos!",
  ["_SeakingDexEntry"] = "En otoño, cuando\nse reproducen,\npueden ser vistos\12nadando con\nenergía por ríos\ny arroyos",
