  ["_SentToBoxText"] = "¡No tienes sitio\npara más POKéMON!\11¡{RAM:wBoxMonNicks}\11fue enviado a la\11CAJA POKéMON\11{RAM:wStringBuffer} del PC!",
  ["_ShallWeHealYourPokemonText"] = "¿Quieres que\ncuremos a tus\11POKéMON?",
  ["_ShellderDexEntry"] = "Su caparazón\nrepele cualquier\ntipo de ataque.\12Sólo cuando abre\nsu caparazón es\nvulnerable",
  ["_ShroudedInMistText"] = "¡{USER}\npadece neblina!",
  ["_SilphCo10FGiovanniILostAgainText"] = "¡¡Arr!!\n¿¡He vuelto a\11perder!?",
  ["_SilphCo10FPorygonText"] = "¡Hay un POKéMON\nen el monitor!",
  ["_SilphCo10FRocketAfterBattleText"] = "¡Bien jugado,\npero la sala del\11consejo está un\11piso más arriba!",
  ["_SilphCo10FRocketBattleText"] = "¡Bienvenido al\nnoveno piso!\11¡Me alegra que\11hayas venido!",
  ["_SilphCo10FRocketEndBattleText"] = "¡Estoy\naturdido!",
