  ["_SilphCo10FSilphWorkerFImScaredText"] = "¡Uauuu!\n¡Tengo miedo!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "¡Por favor, no le\ndigas a nadie que\11he llorado!",
  ["_SilphCo11FBeautyText"] = "SECRETARIA:\n¡Gracias por\11salvarnos!\12Admiramos\ntu valor.",
  ["_SilphCo11FGiovanniText"] = "¡Hola {PLAYER}!\n¡Volvemos a\11encontrarnos!\12¡El PRESIDENTE y\nyo estamos\11hablando de algo\11muy importante!\12¡No te metas\nen los asuntos\11de los mayores!\12¡O sufrirás\nmi ira!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "¡Qué mal!\n¡Arruinaste\11nuestros planes\11con respecto a\11SILPH!\12¡Pero el TEAM\nROCKET no caerá\11jamás!\12¡{PLAYER}, no\nolvides jamás\11que todos los\11POKéMON son\11para el\11TEAM ROCKET!\12¡Ahora debo irme,\npero volveré!",
  ["_SilphCo11FRocket1AfterBattleText"] = "¿¡Qué!? ¿Quieres\nver a mi JEFE?",
  ["_SilphCo11FRocket1BattleText"] = "¡Alto ahí!\n¡No te muevas!",
  ["_SilphCo11FRocket1EndBattleText"] = "No...\n¡Por favor!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Ten cuidado,\n¡Los POKéMON\11de mi JEFE son\11terribles!",
  ["_SilphCo11FRocket2BattleText"] = "¡Alto! ¿Tienes\nuna cita con\11mi JEFE?",
  ["_SilphCo11FRocket2EndBattleText"] = "¡Auch!\n¡Derribado!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRESIDENTE: ¡No\npuedes comprarla\11en ningún sitio!\12¡Es nuestro\nprototipo secreto\11de la\11MASTER BALL!\12¡Puede atrapar a\ncualquier tipo\11de POKéMON!\12Pero mejor que\nno se lo digas\11a nadie.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "No tienes sitio\npara esto.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "¡{PLAYER} ganó\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRESIDENTE:\n¡Gracias por\11salvar a SILPH!\12¡Jamás olvidaré\nque nos salvaste\11en este peligroso\11momento!\12¡Me gustaría\nagradecértelo\11de alguna forma!\12Como soy rico,\n¡puedo darte\11lo que quieras!\12¡Toma, puede que\nte interese!",
  ["_SilphCo1FLinkReceptionistText"] = "¡Bienvenido!\12¡El PRESIDENTE\nestá en la sala\11de reuniones\11del P10!",
  ["_SilphCo2FRocket1AfterBattleText"] = "¡Las baldosas con\nforma de diamante\11son puntos de\11teletransporte!\12¡Son medios de\ntransporte de\11alta tecnología!",
  ["_SilphCo2FRocket1BattleText"] = "¡Aquí no pueden\nentrar los niños!",
  ["_SilphCo2FRocket1EndBattleText"] = "\n¡Muy fuerte!",
  ["_SilphCo2FRocket2AfterBattleText"] = "¡SILPH S.A. va a\nfusionarse con\11el TEAM ROCKET!",
  ["_SilphCo2FRocket2BattleText"] = "¡Oye tú, niño!\n¿Qué haces aquí?",
  ["_SilphCo2FRocket2EndBattleText"] = "¡He\nmetido la pata!",
  ["_SilphCo2FScientist1AfterBattleText"] = "¡Trabajo para\nSILPH S.A. y para\11el TEAM ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "¡Socorro! ¡Soy\nun empleado de\11SILPH S.A.!",
  ["_SilphCo2FScientist1EndBattleText"] = "\n¿Cómo sabías que\11yo era un ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "¿Puedes resolver\neste laberinto?",
  ["_SilphCo2FScientist2BattleText"] = "¡Estás en zona\nprohibida!\11¡Vuelve a casa!",
  ["_SilphCo2FScientist2EndBattleText"] = "¡Eres\nmuy bueno!",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "¡{PLAYER} obtiene\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "¡La MT36 es\nAUTODESTRUCCIÓN!\12¡Es muy potente,\npero el POKéMON\11que la use se\11debilitará mucho!\11¡Ten cuidado!",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "¡No tienes sitio\npara esto!",
