  ["_SilphCo3FScientistEndBattleText"] = "¡Me\nhas derrotado!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Trabajo para\nSILPH S.A. ¿Qué\11debería hacer?",
