  ["_SilphCo4FScientistEndBattleText"] = "\n¡Debilitaste a\11mi POKéMON!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "¡Sssh! ¿Acaso no\nves que me estoy\11escondiendo?",
