  ["_SilphCo5FRockerAfterBattleText"] = "¡Sólo has llegado\nal 4P! ¡Mi JEFE\11aún está muy\11lejos!",
  ["_SilphCo5FRockerBattleText"] = "¿Qué? ¡Aquí no\ndebería haber\11ningún niño!",
  ["_SilphCo5FRockerEndBattleText"] = "\n¡Oh no!\11¡Dios mío!",
  ["_SilphCo5FRocket1AfterBattleText"] = "¡No es que sea\nmuy inteligente\11provocar al\11TEAM ROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Dicen que había\nun niño por\11aquí.",
  ["_SilphCo5FRocket1EndBattleText"] = "¡Boooom!",
