  ["_SilphCo5FRocket2EndBattleText"] = "\n(Tos)... (Tos)...",
  ["_SilphCo5FScientistAfterBattleText"] = "¡Trabajamos en\nuna nueva\11POKé BALL capaz\11de atraparlo\11todo!",
