  ["_SilphCo5FScientistEndBattleText"] = "¡Uff!\n¡Maldición!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "El TEAM ROCKET\nestá buscando a\11un intruso. Te\11buscan a ti ¿no?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "¡El TEAM ROCKET\nse fue! ¡Gracias!\11¡Eres un héroe!",
  ["_SilphCo6FRocket1AfterBattleText"] = "¡No importa!\n¡Mis hermanos me\11vengarán!",
