  ["_SilphCo6FRocket2EndBattleText"] = "¡Eres\nun traidor!",
  ["_SilphCo6FScientistAfterBattleText"] = "¿La SUCURSAL\nTIKSI? ¡Está\11en mitad de\11la nada!",
  ["_SilphCo6FScientistBattleText"] = "¡Ese podrido\nPRESIDENTE!\12¡No debía haberme\nenviado a la\11SUCURSAL TIKSI!",
  ["_SilphCo6FScientistEndBattleText"] = "\n¡Estoy acabado!",
