  ["_SilphCo7FRocket2EndBattleText"] = "\n¡Auch! ¡Hermanos,\11he perdido!",
  ["_SilphCo7FRocket3AfterBattleText"] = "¡Vete a casa\nantes de que se\11enfade mi JEFE!",
  ["_SilphCo7FRocket3BattleText"] = "¿Un niño intruso?\n¡Debes de ser tú!",
  ["_SilphCo7FRocket3EndBattleText"] = "¡Vale!\n¡He perdido!",
  ["_SilphCo7FScientistAfterBattleText"] = "¡A pesar de tu\nedad, eres un\11buen entrenador!",
  ["_SilphCo7FScientistBattleText"] = "¡Ejem!\12¿Me confundiste\ncon un empleado\11de SILPH?",
  ["_SilphCo7FScientistEndBattleText"] = "\n¡Estoy acabado!",
