  ["_VileplumeDexEntry"] = "A mayor pétalo,\nmás tóxico es su\npolen. Su\12cabeza es pesada\ny le cuesta\nmantenerla",
  ["_ViridianBlackboardBurnText"] = "Toda quemadura\nreduce potencia\11y velocidad. Y\11causa daños\11progresivos.\12Las quemaduras\npermanecerán tras\11el combate.\12¡ANTIQUEMADURAS\ncurará las\11quemaduras!",
  ["_ViridianBlackboardFrozenText"] = "¡Todo POKéMON\ncongelado no\11podrá moverse!\12Y permanecerá\ncongelado tras\11el combate.\12¡Usa el ANTIHIELO\npara descongelar\11a los POKéMON!",
  ["_ViridianBlackboardPoisonText"] = "Todo POKéMON\nenvenenado\11seguirá perdiendo\11energía.\12El veneno sigue\nafectándoles tras\11el combate.\12¡Usa un ANTÍDOTO\npara curarlos!",
  ["_ViridianBlackboardPrlzText"] = "¡Paralizar podría\nanular ciertos\11movimientos!\12La parálisis\npermanecerá tras\11el combate.\12Usa ANTIPARALIZAR\npara curarlos.",
  ["_ViridianBlackboardSleepText"] = "¡Un POKéMON no\npuede atacar si\11está dormido!\12¡Los POKéMON\nseguirán dormidos\11incluso después\11de pelear!\12¡Usa DESPERTAR y\nse despertarán!",
