  ["_ViridianCityGymSignText"] = "GIMNASIO POKéMON\nde CIUDAD VERDE",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "¡Ya me tomé\nun café y me\11siento genial!\12¡Claro que\npuedes pasar!\12¡Siento haber sido\ntan grosero!\12Veo que usas\nuna POKéDEX.\12Te enseñaré a\natrapar POKéMON\vcomo disculpa.",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Ya veo que tienes\nuna POKéDEX.\12Cuando atrapes un\nPOKéMON, la\11POKéDEX será\11automáticamente\11actualizada.\12¿Qué? ¿No sabes\ncómo atrapar un\11POKéMON?\12Pues yo te\nenseñaré.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "¡No puedes pasar\npor aquí!\12¡Es propiedad\nprivada!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "El tiempo es oro.\nSigue tu camino.",
