  ["_ViridianCityPokecenterGuyText"] = "¡Los CENTROS\nPOKéMON curan\11a tus POKéMON\11heridos o\11derrotados!",
  ["_ViridianCitySignText"] = "CIUDAD VERDE\nEl Paraíso del\11eterno verdor.",
  ["_ViridianCityTrainerTips1Text"] = "PISTAS ENTRENADOR\12¡Atrapa a los\nPOKéMON y amplía\11tu colección!\12¡Cuantos más\ntengas más fácil\11te será luchar!",
  ["_ViridianCityTrainerTips2Text"] = "PISTAS ENTRENADOR\12Los ataques de\nlos POKéMON\11dependen de sus\11PUNTOS DE\11PODER o PP.\12¡Para rellenar\ntus PP, deja que\11tus cansados\11POKéMON\11descansen en un\11CENTRO POKéMON!",
  ["_ViridianCityYoungster1Text"] = "¡Esas POKé BALL\nde tu cintura!\11¡Tienes POKéMON!\12¡Es genial poder\nllevar y usar los\11POKéMON en\11cualquier momento\11y lugar!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "¿Quieres saber\nalgo sobre los 2\11tipos de orugas\11POKéMON?",
  ["_ViridianForestLeavingSignText"] = "SALIENDO DEL\nBOSQUE VERDE. LA\11CIUDAD PLATEADA\11ESTÁ ENFRENTE.",
  ["_ViridianForestNorthGateGrampsText"] = "¿Has visto los\narbustos que hay\11junto al camino?\12Puedes cortarlos\ncon un movimiento\11especial de los\11POKéMON.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Muchos POKéMON\nsólo viven en\11bosques y cuevas.\12¡Tienes que mirar\npor todas partes\11para conseguirlos\11todos!",
  ["_ViridianForestSouthGateGirlText"] = "¿Piensas ir al\nBOSQUE VERDE?\11¡Ten cuidado!\11¡Es un auténtico\11laberinto!",
  ["_ViridianForestSouthGateLittleGirlText"] = "Hay que viajar\nlejos para ver\11nuevos POKéMON.\12Busca otros tipos\nfuera del BOSQUE\11VERDE.",
  ["_ViridianForestTrainerTips1Text"] = "PISTAS ENTRENADOR\12Si quieres evitar\nlos combates,\11¡aléjate de las\11zonas de hierba!",
  ["_ViridianForestTrainerTips2Text"] = "PISTAS ENTRENADOR\12¡Para evaluar tu\nPOKéDEX, llama\11al PROF. OAK\11vía PC!",
  ["_ViridianForestTrainerTips3Text"] = "PISTAS ENTRENADOR\12¡No robes los\nPOKéMON\11de otros\11entrenadores!\11¡Captura sólo a\11los POKéMON\11salvajes!",
  ["_ViridianForestTrainerTips4Text"] = "PISTAS ENTRENADOR\12¡Debilita a los\nPOKéMON antes\11de intentar\11capturarlos!\12¡Si están\nfuertes,\11podrían escapar!",
  ["_ViridianForestUseAntidoteSignText"] = "¡Usa ANTÍDOTO\ncontra el veneno!\11¡Lo conseguirás\11en las TIENDAS\11POKéMON!",
  ["_ViridianForestYoungster1Text"] = "¡Vine aquí con\nunos amigos!\12¡Van en busca\nde peleas de\11POKéMON!",
