  ["_ViridianForestYoungster2BattleText"] = "¡Eh! ¡Tienes\nPOKéMON! ¡Sí!\11¡Al ataque!",
  ["_ViridianForestYoungster2EndBattleText"] = "¡No!\n¡CATERPIE no\11pudo cortarlo!",
  ["_ViridianForestYoungster3AfterBattleText"] = "¡Maldición! \n¡Voy a atrapar\11unos más fuertes!",
  ["_ViridianForestYoungster3BattleText"] = "¡Eh! ¡Debes\nser disciplinado\11para ser un\11entrenador de\11POKéMON!",
