  ["_ViridianGymCooltrainerM3EndBattleText"] = "\n¿Acaso fui\11derrotado?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "¡Con la MEDALLA-\nTIERRA, todos los\11POKéMON te\11obedecerán!\12¡Es una prueba de\ntu maestría como\11entrenador de\11POKéMON!\12¡Con ella podrás\nacceder a la\11LIGA POKéMON!\12¡Es mi regalo por\ndesafiar a la\11LIGA POKéMON!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "¡Como perdí, ya\nno soy digno de\11dirigir a mis\11secuaces! ¡Se\11acabó el TEAM\11ROCKET!\12¡Dedicaré mi vida\nal estudio de\11los POKéMON!\12¡Espero que nos\nvolvamos a ver!\11¡Adiós!",
  ["_ViridianGymGiovanniPreBattleText"] = "¡Ajajaja! ¡Ésta\nes mi guarida!\12¡Quería reformar\nal TEAM ROCKET\11desde aquí!\12¡Pero me volviste\na encontrar!\11¡Estoy furioso!\11¡Esta vez no me\11pienso contener!\12¡Volverás a\nenfrentarte al\11gran GIOVANNI, el\11súper entrenador!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "¡Ja!\n¡Fue un duro\11combate! ¡Y has\11ganado! ¡Como\11premio, toma esta\11MEDALLA-TIERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "¡{PLAYER} ganó\nla MT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\12¡MT27 es FISURA!\n¡Ésta derrotará\11a los POKéMON de\11un solo ataque!\12La inventé cuando\ndirigía este\11GIMNASIO, hace ya\11mucho tiempo...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "¡No tienes sitio\npara esto!",
  ["_ViridianGymGuidePostBattleText"] = "¿Qué dices? ¿Que\nGIOVANNI era el\11LÍDER del\11GIMNASIO?",
  ["_ViridianGymGuidePreBattleText"] = "¡Hola,\nposible campeón!\12¡Ni yo conozco\nla identidad del\11LÍDER VERDE!\12¡Éste será el más\nduro de todos los\11LÍDERES-GIMNASIO!\12¡Dicen que estos\nentrenadores usan\11los POKéMON\11del tipo TIERRA!",
  ["_ViridianGymHiker1AfterBattleText"] = "¡Sigo sin\nmerecérmelo!",
  ["_ViridianGymHiker1BattleText"] = "¡Groaar! ¡Estoy\nempezando a\11enfurecerme!",
  ["_ViridianGymHiker1EndBattleText"] = "¡Rargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Si mis POKéMON\nfueran tan buenos\11karatekas...",
  ["_ViridianGymHiker2BattleText"] = "¡El karate es lo\nmáximo en artes\11marciales!",
  ["_ViridianGymHiker2EndBattleText"] = "¡Aachú!",
  ["_ViridianGymHiker3AfterBattleText"] = "¿La LIGA POKéMON?\n¿Tú? ¿Pero quién\11te crees?",
  ["_ViridianGymHiker3BattleText"] = "¡Soy el REY del\nKARATE! ¡Te tengo\11en mis manos!",
  ["_ViridianGymHiker3EndBattleText"] = "¡Yaha!",
